WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY discount_pct ASC, id ASC) AS row_num FROM promotions QUALIFY row_num = 1), metrics AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, row_num, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) discount_pct_share, SUM(discount_pct) OVER (ORDER BY ends_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_discount_pct FROM latest), kept_keys AS (SELECT promo_code, channel FROM metrics EXCEPT SELECT promo_code, channel FROM promotions WHERE starts_on >= '2024-05-01'), verified AS (SELECT s.* FROM metrics s JOIN kept_keys k ON s.promo_code = k.promo_code AND s.channel = k.channel) SELECT CASE WHEN discount_pct_share >= 0.66 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_share_tier, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, MAX(discount_pct_share) FILTER (WHERE channel = 'partner') AS partner_max_discount_pct_share, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, COUNT(*) AS num_rows, COUNT(DISTINCT id) AS distinct_ids FROM verified GROUP BY CASE WHEN discount_pct_share >= 0.66 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY distinct_ids ASC NULLS FIRST
